with scored as (select *, row_number() over (partition by product_id order by quantity, id) row_seq, last_value(quantity, true) over w_running last_known_quantity from inventory window w_running as (partition by store_id order by last_restock, id rows between unbounded preceding and current row)) select s.id, s.store_id, s.quantity, s.last_restock, s.row_seq, s.last_known_quantity, (select avg(o2.discount) from orders o2 where o2.store_id = s.store_id) as avg_order_discount from scored s order by quantity desc nulls last, row_seq;
